#include "routeguidance.h"
#include "trafficprofile.h"
#include "permanentroutes.h"
#include <chrono>
#include <cstdio>
namespace logger {void Write(const char*,...) {}}
namespace notify {void Show(const char*,...) {}}
namespace fs=std::filesystem;
int main(){int checks=0;const auto sandbox=fs::temp_directory_path()/("fvo-permanent-test-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));try{auto check=[&](bool ok,const char* why){++checks;if(!ok)throw std::runtime_error(why);};const auto defaults=sandbox/"defaults",storage=sandbox/"storage",root=storage/"TrafficProfiles";fs::create_directories(defaults);trafficprofilestore::Write(defaults/"City.ini","ordinary baseline");float saved=0;trafficprofile::testing::Configure(storage.wstring(),defaults.wstring(),&saved,false);trafficprofile::SaveReady(true);trafficprofile::Allow(true);const fs::path working=trafficprofile::Routes();trafficprofile::BeforeSave();trafficprofile::AfterSave();const auto before=std::uint32_t(saved);
    permanentroutes::Entry entry;entry.file.worldId="world";entry.file.traffic=true;routefiles::Route route;route.id="shared";route.world="city";route.ring=false;route.points={{0,0,0},{0,20,5}};route.lanes=1;route.group="cars";route.test=true;route.spacePlan.enabled=true;splinekit::AutoHandles(route.spacePlan,splinekit::Points(route.points),false);trafficdata::Data context;context.worlds["city"]="world";context.anchors["city"]={{0x1234,{1,2,3}}};trafficdata::RouteGroup group;group.name="cars";group.exclude={0x100};context.groups.push_back(group);trafficdata::RouteGroup laneGroup;laneGroup.name="lane_group";laneGroup.exclude={0x200};context.groups.push_back(laneGroup);lanevehicles::Edit(route.lanePlan.vehicles,0).group="lane_group";
    permanentroutes::Put(entry,route,context,{});const auto name=trafficpermanent::FileName("world");const fs::path shared=fs::path(trafficprofile::PermanentDir())/name;
    auto text=permanentroutes::Format(entry);trafficprofilestore::Write(shared,text);std::string why;check(trafficprofile::RefreshPermanent(why),"publish refreshes current working copy");check(trafficpermanent::Read(working/name)==text,"working copy receives complete permanent entry");check(!fs::exists(trafficprofilestore::Open(root,before)/name),"publishing never rewrites existing immutable snapshots");auto parsed=permanentroutes::Parse(text,name,"world");check(parsed.file.routes.size()==1&&!parsed.file.routes[0].test,"permanent authoring never exports active test requests");check(parsed.context.anchors["city"][0].id==0x1234&&parsed.context.groups[0].exclude==group.exclude,"portable anchors and selected group survive publication");check(parsed.context.groups.size()==2&&lanevehicles::Find(parsed.file.routes[0].lanePlan.vehicles,0)&&trafficdata::LaneLeftOut(parsed.context.groups,([&]{trafficdata::Route r;r.lanePlan=parsed.file.routes[0].lanePlan;return r;}()),0,0x200),"permanent routes include lane groups and retain their model exclusions");
    check(splinekit::Write(parsed.file.routes[0].spacePlan)==splinekit::Write(route.spacePlan),"shared geometry retains versioned spline data");
    trafficprofile::BeforeSave();trafficprofile::AfterSave();const auto withShared=std::uint32_t(saved);const auto frozen=trafficpermanent::Read(trafficprofilestore::Open(root,withShared)/name);route.points[0].x=10;permanentroutes::Put(entry,route,context,{});text=permanentroutes::Format(entry);trafficprofilestore::Write(shared,text);check(trafficprofile::RefreshPermanent(why),"permanent updates refresh without changing active working identity");check(trafficpermanent::Read(trafficprofilestore::Open(root,withShared)/name)==frozen,"global update leaves saved snapshot bytes unchanged");saved=float(withShared);trafficprofile::BeginLoad();trafficprofile::Allow(true);const fs::path loaded=trafficprofile::Routes();check(loaded!=working&&trafficpermanent::Read(loaded/name)==text,"loading uses latest explicit shared overlay on a new working branch");check(trafficpermanent::Read(loaded/"City.ini")=="ordinary baseline","ordinary save content is untouched by shared overlay");
    routefiles::File local;local.worldId="world";auto localRoute=route;localRoute.points[0].x=99;local.routes={localRoute};trafficdata::Data data;trafficdata::Read(text,name,data);trafficdata::Read(routefiles::Format(local),"Editor_local.ini",data);trafficdata::PreferEditor(data);check(data.routes.size()==1&&data.routes[0].points[0].x==99,"normal save-local edits override permanent routes");local.routes[0].removed=true;data={};trafficdata::Read(text,name,data);trafficdata::Read(routefiles::Format(local),"Editor_local.ini",data);trafficdata::PreferEditor(data);check(data.routes.empty()&&trafficpermanent::Read(shared)==text,"ordinary Delete hides locally without deleting shared data");
    saved=0;trafficprofile::BeginLoad();trafficprofile::Allow(true);const fs::path other=trafficprofile::Routes();check(other!=loaded&&trafficpermanent::Read(other/name)==text,"permanent route appears in another playthrough");check(!fs::exists(other/"Editor_local.ini")&&!fs::exists(other.parent_path()/"trafficpool.ini"),"local edits and vehicle instance IDs are not shared");
    routefiles::Route second=route;second.id="second";permanentroutes::Put(entry,second,context,{});check(permanentroutes::Erase(entry,"shared")&&entry.file.routes.size()==1&&entry.file.routes[0].id=="second","Permanent Delete removes only the selected shared route");trafficprofilestore::Write(shared,permanentroutes::Format(entry));check(trafficprofile::RefreshPermanent(why),"permanent deletion refreshes current overlay");saved=float(withShared);trafficprofile::BeginLoad();trafficprofile::Allow(true);const fs::path reloaded=trafficprofile::Routes();data={};trafficdata::Read(trafficpermanent::Read(reloaded/name),name,data);check(data.routes.size()==1&&data.routes[0].name=="second","old save cannot resurrect a deleted shared route from its cached overlay");check(trafficpermanent::Read(trafficprofilestore::Open(root,withShared)/name)==frozen,"permanent deletion preserves old history bytes");
    check(trafficpermanent::Disabled("; x\n[file]\nenabled = 0\n")&&!trafficpermanent::Disabled("; x\n[file]\nenabled = 1\n"),"a switched-off shared file is recognised");
    {const auto live=trafficpermanent::Live("Permanent_ab.ini");check(live=="Permanent_ab_live.ini"&&trafficpermanent::Name(fs::path(live)),"new shared routes go beside it, in a name the store still reads");}
    trafficprofilestore::Write(shared,"unowned file");check(!trafficprofile::RefreshPermanent(why)&&!why.empty(),"unrecognized shared files are refused without silent replacement");check(trafficpermanent::Read(shared)=="unowned file","unowned global content is preserved");fs::remove_all(sandbox);std::printf("permanent routes: %d/%d checks passed\n",checks,checks);return 0;
}catch(const std::exception& error){std::printf("FAIL permanent routes: %s (%s)\n",error.what(),sandbox.string().c_str());return 1;}}
